import json, subprocess
p=subprocess.run(['system_profiler','SPUSBDataType','-json'],capture_output=True,text=True,timeout=45)
print('SYSTEM_PROFILER_RC',p.returncode)
if p.returncode:
    print(p.stderr[-4000:]); raise SystemExit(0)
data=json.loads(p.stdout or '{}')
interesting=[]
def walk(x,path=()):
    if isinstance(x,dict):
        name=x.get('_name') or x.get('name') or ''
        np=path+((str(name),) if name else ())
        fields={k:x.get(k) for k in ('_name','manufacturer','vendor_id','product_id','serial_num','location_id','bcd_device','current_available','current_required','extra_current_used') if x.get(k) is not None}
        text=' '.join(str(v) for v in fields.values()).lower()
        if fields and any(k in text for k in ('wch','qin','ch34','ch910','usb serial','uart','silicon labs','cp210','espressif','303a','1a86')):
            interesting.append((np,fields))
        for v in x.values(): walk(v,np)
    elif isinstance(x,list):
        for v in x: walk(v,path)
walk(data)
print('USB_INTERESTING_BEGIN')
for path,fields in interesting:
    print('PATH',' > '.join(path)); print('FIELDS',json.dumps(fields,ensure_ascii=False,sort_keys=True))
print('USB_INTERESTING_END')
print('USB_INTERESTING_COUNT',len(interesting))
